}

class DealLoaderTest {

    private val dealProduct = Product(1, "Banana Bunch", "x", 6_000, "d", 10)

    @Test
    fun cancelledLoadNeverShowsDialog() = runBlocking {
        val gate = CompletableDeferred<Product>()
        var loaded = false
        var dialogShown = false

        val job = launch(Dispatchers.Unconfined, start = CoroutineStart.DEFAULT) {
            DealLoader.load(
                productId = 1,
                fetch = { gate.await() },
                onLoaded = { loaded = true },
